mapper.select:
SELECT distinct
A.ACCT_NO id,
B.SEC_ACCT_NAME text
FROM PTL_SEC_ACCT A
INNER JOIN STL_SEC_ACCT_INFO B
ON A.ACCT_NO = B.SEC_ACCT_ID

    LEFT JOIN FIN_PRODUCT FP
    ON FP.FINPROD_ID IN (

        #{item}

    )



        AND A.PORTFOLIO_ID IN(

            #{item}

        )


        AND
        (
        A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%'))
        OR
        B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
        )


        AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR
        (PORTFOLIO_ID || A.ACCT_NO) = #{initValue, jdbcType=VARCHAR}
        )


        AND B.TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}


        AND B.TRADE_PLACE = FP.TRADE_MARKET

sql.where:
T1.FINPROD_TYPE2 = #{assestType}
AND T1.TRADE_MARKET in(#{TRADE_PLACE_01},#{TRADE_PLACE_02})

    and T1.FINPROD_MARKET_ID = #{initValue}


    and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
    or T1.FINPROD_NAME like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ABBR like concat('%',concat(#{search},'%'))
    or T1.FINPROD_ID like concat('%',concat(#{search},'%'))
    )

mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object, A.PROFIT_TYPE col FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON A.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
(A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID id, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME text, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID parentId FROM (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN( SELECT nvl(t2.mparty_id,t1.party_id) PARTY_ID from MST_CFETS_CUSTOMER_INFO t1 LEFT JOIN MST_CFETS_CUSTOMER_RELA t2 on t1.party_id = t2.sparty_id WHERE 1 = 1
AND t1.PARTY_ID = #{mySide}
AND t1.PARTY_ID = #{counterId}
) t3 on MST_CFETS_CUSTOMER_TRADER.PARTY_ID = t3.PARTY_ID ) MST_CFETS_CUSTOMER_TRADER WHERE 1 = 1
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{search},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{search},'%')))

select
sum(t.amount) as amount
from ETR_CASH_POSITION t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.acct_id = #{acctId,jdbcType=VARCHAR}


    and t.chl_finprod_id = #{chlFinprodId,jdbcType=VARCHAR}

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate = #{cdate,jdbcType=DATE}
and t.ccy = #{ccy,jdbcType=VARCHAR}

    and t.acct_id in (
    select t1.acct_no from ptl_capacct_info t1
    where t1.acct_type in

        #{item}

    and t1.portfolio_id = #{portfolioId,jdbcType=VARCHAR}
    )

